#!/usr/bin/env python3
"""
Round 190o (culprits-tiles-more), 8 October 2026.

- iea_methane.py (new): methane from oil and gas, each country, from the
  IEA Global Methane Tracker 2026 downloads (methane/iea/, CC BY 4.0).
  Writes methane/iea_oilgas.places.geojson, .boxes.json and .build.json;
  this patch carries a first build of them, so the row draws at once.

Written only if it differs. Run from the repository root (apply-patch does).
"""
import base64, pathlib, sys

FILES = {'scripts/iea_methane.py': '', 'methane/iea/by_source.csv': '', 'methane/iea/abatement.csv': '', 'methane/iea/gas_prices.csv': '', 'methane/iea/comparison.csv': '', 'methane/iea_oilgas.places.geojson': '', 'methane/iea_oilgas.boxes.json': '', 'methane/iea_oilgas.build.json': ''}

def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("round190o_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round190o_tiles: wrote {path}")
    if not changed:
        print("round190o_tiles: already applied")


if __name__ == "__main__":
    main()
